import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { AppHeader } from '../../slots/defs/appHeader';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { type Sheet, sheetKey, useSheet } from './sheet';

function SheetToday() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const loaded = useSheet(sheet);
  const [input, setInput] = useState('');
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: (today: string) =>
      postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheet)}/today`, { today, user }),
    // A new today changes every date decision on the sheet: re-read all of it.
    onSuccess: () => queryClient.invalidateQueries({ queryKey: sheetKey(sheet) }),
  });
  const submit = useSubmitOnce(save);

  if (!user || !loaded.data) return null;
  return (
    <form
      data-testid="sheet-today-form"
      onSubmit={(e) => {
        e.preventDefault();
        submit(input.trim());
      }}
    >
      Today <strong data-testid="sheet-today">{loaded.data.today}</strong>{' '}
      <input
        data-testid="sheet-today-input"
        type="date"
        value={input}
        onChange={(e) => {
          setInput(e.target.value);
          save.reset();
        }}
      />
      <button type="submit" data-testid="sheet-today-save">
        Set today
      </button>
      {save.isError && (
        <span data-testid="sheet-error" role="alert">
          {' '}Not a valid date.
        </span>
      )}
    </form>
  );
}

export const contribution = AppHeader.fill({ order: 20, Component: SheetToday });
import { Outlet, createRootRouteWithContext } from '@tanstack/react-router';
import type { QueryClient } from '@tanstack/react-query';
import { AppNav } from '../slots/defs/appNav';
import { AppHeader } from '../slots/defs/appHeader';

// The shell. It renders the nav region (filled from app.nav) and the matched route's component
// (from routes/); it reads no page list and holds no view state — URL search params carry what is
// open or filtered.
export const Route = createRootRouteWithContext<{ queryClient: QueryClient }>()({
  // Search params are an open namespace, declared once here and inherited by every route: a key is
  // used by reading/writing it (url/useSearchParam), with no per-key schema.
  validateSearch: (search: Record<string, unknown>) => search,
  component: AppShell,
});

function AppShell() {
  return (
    <div data-testid="app-root">
      <header data-testid="app-header">
        <AppHeader.Slot />
      </header>
      <nav data-testid="app-nav">
        <AppNav.Slot />
      </nav>
      <main data-testid="app-home">
        <Outlet />
      </main>
    </div>
  );
}
