export const useShowRetired = () => useSearchParam('showRetired', asFlag);
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { useCurrentSheet } from '../../session/session';
import { useEditingPerson, usePeople, useShowRetired } from './people';

// The sheet's people in the order they were added; retired people only while "show retired" is on.
function PeopleList() {
  const [sheet] = useCurrentSheet();
  const [, setEditing] = useEditingPerson();
  const people = usePeople(sheet);
  const [showRetired] = useShowRetired();

  return (
    <table data-testid="people">
      <thead>
        <tr>
          <th>Name</th>
          <th>Grade</th>
          <PersonColumnHeads.Slot />
          <th />
        </tr>
      </thead>
      <tbody>
        {(people.data ?? []).filter((p) => showRetired || !p.retired).map((p) => (
          <tr key={p.id} data-testid={`person-row-${p.id}`}>
            <td data-testid="person-name" style={{ whiteSpace: 'pre' }}>{p.name}</td>
            <td data-testid="person-grade">{p.grade}</td>
            <PersonColumns.Slot person={p} />
            <td>
              <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => setEditing(String(p.id))}>
    halfUp: (c) => policy !== undefined && (c.roundsBy ?? c.date) < policy,
  };
}

/** A person's overdue claims among these (their claims that count): how many, and the sum of their
 *  dues (late charge included) at the person's grade in force on each claim's date, skipping n/a. */
export function overdueFigures(
  claims: Claim[],
  rates: Rate[] | undefined,
  grades: Grades,
  floor: string | undefined,
  today: string | undefined,
  lateCharge?: Late,
): { count: number; total: string } {
  const late = claims.filter((c) => overdue(c, today));
  return { count: late.length, total: dueTotal(late.map((c) => claimDue(c, rates, grades, floor, lateCharge))) };
}

